use verus::prelude::*;

/// Returns the maximum element of a non-empty vector of i8.
///
/// Specification:
///   - Precondition: `a.len() > 0`
///   - Postconditions:
///       * The result is at least as large as every element of the original vector.
///       * The result is equal to one of the elements of the original vector.
///
/// We mark this function as `trusted` so that we can rely on the
/// standard library's Iterator::max() implementation without re-proving it here.
#[verifier::trusted]
#[requires(a.len() > 0)]
#[ensures(
    // For every index i in the original vector, result >= old(a)[i]
    forall(|i: usize| i < old(a).len() ==> result >= old(a)[i])
)]
#[ensures(
    // There exists an index i such that result == old(a)[i]
    exists(|i: usize| i < old(a).len() && result == old(a)[i])
)]
fn max(a: Vec<i8>) -> i8 {
    // Since the vector is guaranteed non-empty, unwrap() is safe here.
    a.into_iter().max().unwrap()
}

